CREATE TABLE Departamentos (DepartamentoID INTEGER PRIMARY KEY, Nombre TEXT NOT NULL, Ciudad TEXT);
CREATE TABLE Empleados (EmpleadoID INTEGER PRIMARY KEY, Nombre TEXT NOT NULL, Salario REAL, DepartamentoID INTEGER REFERENCES Departamentos(DepartamentoID), JefeID INTEGER REFERENCES Empleados(EmpleadoID), FechaAlta TEXT);
CREATE TABLE Clientes (ClienteID INTEGER PRIMARY KEY, Nombre TEXT NOT NULL, Ciudad TEXT, Email TEXT);
CREATE TABLE Productos (ProductoID INTEGER PRIMARY KEY, Nombre TEXT NOT NULL, Precio REAL NOT NULL, Stock INTEGER NOT NULL, Categoria TEXT);
CREATE TABLE Pedidos (PedidoID INTEGER PRIMARY KEY, ClienteID INTEGER REFERENCES Clientes(ClienteID), Fecha TEXT, Estado TEXT);
CREATE TABLE LineasPedido (PedidoID INTEGER REFERENCES Pedidos(PedidoID), ProductoID INTEGER REFERENCES Productos(ProductoID), Cantidad INTEGER NOT NULL, PRIMARY KEY (PedidoID, ProductoID));
